/**
 * @file pcm_bits_to_symbol.h
 * @brief Transmit bit-to-symbol front ends of the V.90 and V.92 modulators.
 *
 * Declares three classes (definitions in pcm_bits_to_symbol.cpp; layout asserts in pcm_bits_to_symbol_layout.inc, generated by tools/layout_gen.py):
 * - V92Transmitter: collects `w0_` data bits, runs them through the modulus encoder (twelve digits), three passes of precoder and convolutional encoder
 *   (four symbols each), the pre-filter, and applies the gain (result truncated to 16 bits), giving twelve symbols per group of `w0_` bits.
 * - V90BitsToSymbol and V92BitsToSymbol: a queue of 16-bit symbols (`buf_`, capacity `cap_`) between the bit mapper (V90Mapper: six symbols per frame;
 *   V92Transmitter: twelve symbols per group) and the modulator, which asks for symbols in blocks of `blk_` (setSymbolsBlockSize()).
 *   nofBitsForNextTime() and the bit count written back by process() say how many data bits the next call must bring to complete the block (whole
 *   frames only).  process() returns 0 = ok, 1 = block size not set, 2 = queue overflow, 3 = underflow (a block was asked for before enough symbols
 *   were queued).
 */
#ifndef DSP_CLASSES_P29_H
#define DSP_CLASSES_P29_H

#include "core/dsp_cxx.h"
#include "pcm_leaf_classes.h"    /* PcmType */
#include "pcm_parameters.h"      /* V90Parameters, V92Parameters */
#include "v92_cp.h"              /* V90MappingParams, V92MappingParams */
#include "v92_modulus_encoder.h" /* V92ModulusEncoder */
#include "v92_tx_coding.h"       /* V92Precoder, V92PreFilter, V92ConvolutionEncoder */
#include "v90_mapper.h"          /* V90Mapper */

class V92Transmitter
{
public:
  /** @brief Allocate the work buffer, the modulus encoder, the convolutional encoder, the precoder and the pre-filter. */
  V92Transmitter();
  /** @brief Destroy and free everything the constructor allocated. */
  ~V92Transmitter();
  /** @brief Load the mapping parameters (gain, bits per group, coefficients, trellis type) and clear the running state; may print them at debug level 2. */
  void reset(V92MappingParams* p);
  /** @brief Encode `n` data bits (one per byte) into symbols: twelve symbols per `w0_` bits are written to `out`, their count to `outCnt`. */
  void process(unsigned char* bits, unsigned n, short* out, unsigned& outCnt);

public:
  unsigned char unk0_[4];     ///< never touched
  unsigned w0_;               ///< data bits per group
  unsigned char* buf_;        ///< collected data bits, one per byte (0x50 bytes allocated)
  unsigned fill_;             ///< number of bits in `buf_`
  unsigned digits_[12];       ///< the twelve digits of the modulus encoder for the current group
  int par_;                   ///< parity / state carried from one convolutional encoder pass to the next
  float gain_;                ///< output gain, copied from the mapping parameters
  V92ModulusEncoder* me_;     ///< modulus encoder
  V92Precoder* pre_;          ///< precoder
  V92PreFilter* pf_;          ///< pre-filter
  V92ConvolutionEncoder* ce_; ///< convolutional (trellis) encoder
  unsigned char* flag_;       ///< one allocated byte, cleared by reset(), otherwise unused
  unsigned char pad5c_[4];    ///< never touched
};

class V90BitsToSymbol
{
public:
  /** @brief Create the mapper and a symbol queue of `cap` entries.  The block size starts unset (0). */
  V90BitsToSymbol(unsigned cap, V90Parameters* p);
  /** @brief Destroy the mapper and free the queue. */
  ~V90BitsToSymbol();
  /** @brief Reset for a new connection: reset the mapper, take the bits per frame and the leading symbol allowance from `mp`, empty the queue. */
  void reset(V90MappingParams* mp, PcmType pcm);
  /** @brief Reset the mapper without spectral shaping and take the bits per frame; the queue and block size are left alone. */
  void resetNoSpectral(V90MappingParams* mp, PcmType pcm);
  /** @brief Number of data bits the next process() call must bring to fill a block (0 if the queue already holds one). */
  unsigned nofBitsForNextTime();
  /** @brief Set the block size to `n` symbols.  @return the number of data bits needed to fill it from the current queue content. */
  unsigned setSymbolsBlockSize(unsigned n);
  /** @brief Map `n` bits, queue the symbols and deliver one block to `out`; `n` receives the bit count the next call needs.  @return 0, 1, 2 or 3 */
  unsigned process(unsigned char* in, unsigned& n, short* out);
  /** @brief Map `n` bits and queue the symbols only.  @return 0, 1 or 2 */
  unsigned process(unsigned char* in, unsigned n);
  /** @brief Deliver one block from the queue to `out`; `n` receives the bit count the next call needs.  @return 0, 1 or 3 */
  unsigned process(unsigned& n, short* out);

public:
  V90Mapper* mapper_;      ///< bit-to-symbol mapper
  V90Parameters* params_;  ///< V.90 parameters the mapper was built with
  short* buf_;             ///< symbol queue (2 * cap_ bytes allocated)
  unsigned cap_;           ///< queue capacity in symbols
  unsigned fill_;          ///< symbols currently queued
  unsigned w0_;            ///< data bits per frame of six symbols
  unsigned extra_;         ///< extra symbols counted on the first call after reset()
  unsigned blk_;           ///< block size in symbols, 0 = not set
  unsigned char first_;    ///< 1 until the first process() call after reset()
  unsigned char pad21_[3]; ///< padding
};

class V92BitsToSymbol
{
public:
  /** @brief Create the V92Transmitter and a symbol queue of `cap` entries.  The block size starts unset (0). */
  V92BitsToSymbol(unsigned cap, V92Parameters* p);
  /** @brief Destroy the transmitter and free the queue. */
  ~V92BitsToSymbol();
  /** @brief Reset the transmitter from `mp`, take the bits per group and empty the queue and block size. */
  void reset(V92MappingParams* mp);
  /** @brief Number of data bits the next process() call must bring to fill a block (0 if the queue already holds one). */
  unsigned nofBitsForNextTime();
  /** @brief Set the block size to `n` symbols.  @return the number of data bits needed to fill it from the current queue content. */
  unsigned setSymbolsBlockSize(unsigned n);
  /** @brief Encode `n` bits, queue the symbols and deliver one block to `out`; `n` receives the bit count the next call needs.  @return 0, 1, 2 or 3 */
  unsigned process(unsigned char* in, unsigned& n, short* out);
  /** @brief Encode `n` bits and queue the symbols only.  @return 0, 1 or 2 */
  unsigned process(unsigned char* in, unsigned n);
  /** @brief Deliver one block from the queue to `out`; `n` receives the bit count the next call needs.  @return 0, 1 or 3 */
  unsigned process(unsigned& n, short* out);

public:
  V92Transmitter* tx_;     ///< bit-to-symbol encoder
  V92Parameters* params_;  ///< V.92 parameters
  short* buf_;             ///< symbol queue (2 * cap_ bytes allocated)
  unsigned cap_;           ///< queue capacity in symbols
  unsigned fill_;          ///< symbols currently queued
  unsigned w0_;            ///< data bits per group of twelve symbols
  unsigned blk_;           ///< block size in symbols, 0 = not set
  unsigned char first_;    ///< 1 until the first process() call after reset()
  unsigned char pad1d_[3]; ///< padding
};

typedef V92Transmitter P29_V92Transmitter;
typedef V90BitsToSymbol P29_V90BitsToSymbol;
typedef V92BitsToSymbol P29_V92BitsToSymbol;

#include "pcm_bits_to_symbol_layout.inc"

#if defined(__x86_64__)
/* object sizes of the 64-bit build, which the 64-bit test harness maps back to the 32-bit sizes */
DSP_STATIC_ASSERT(sizeof(V90Mapper) == 0x728, "x86-64 sizeof V90Mapper");
DSP_STATIC_ASSERT(sizeof(V92Transmitter) == 0x80, "x86-64 sizeof V92Transmitter");
DSP_STATIC_ASSERT(sizeof(V92Precoder) == 0xa8, "x86-64 sizeof V92Precoder");
DSP_STATIC_ASSERT(sizeof(V92PreFilter) == 0x20, "x86-64 sizeof V92PreFilter");
#endif

#endif /* DSP_CLASSES_P29_H */
